/**
 * Fast search helper for Pakistani food database
 * @param {string} query
 * @param {string} [category]
 * @returns {Array}
 */
export function searchPakistaniFoods(query = '', category = 'All') {
  const q = (query || '').trim().toLowerCase();
  return PAKISTANI_FOODS.filter(item => {
    const matchesCat = (!category || category === 'All') ? true : item.category === category;
    if (!matchesCat) return false;
    if (!q) return true;
    return (
      item.name.toLowerCase().includes(q) ||
      (item.urdu && item.urdu.includes(q)) ||
      item.category.toLowerCase().includes(q) ||
      (item.prepNotes && item.prepNotes.toLowerCase().includes(q))
    );
  });
}

/**
 * Retrieve food item by ID
 * @param {string} id
 * @returns {Object|null}
 */
export function getPakistaniFoodById(id) {
  if (!id) return null;
  return PAKISTANI_FOODS.find(item => item.id === id) || null;
}

/**
 * Calculate nutrient amounts for a given food and quantity
 * @param {Object} foodItem - Food item object with per100g and serving info
 * @param {number} quantity - Quantity in specified unit
 * @param {string} unit - 'g', 'ml', 'serving', 'piece', 'cup', 'plate', 'roti', etc.
 * @returns {Object} Calculated nutrients
 */
export function calculateServingNutrients(foodItem, quantity = 100, unit = 'g') {
  if (!foodItem || !foodItem.per100g) return null;

  let totalGrams = 100;
  const numQty = parseFloat(quantity) || 0;

  if (unit === 'g' || unit === 'ml') {
    totalGrams = numQty;
  } else if (unit === 'serving' || unit === foodItem.servingUnit) {
    totalGrams = numQty * (foodItem.servingWeightGrams || 100);
  } else {
    // Default factor fallback
    totalGrams = numQty * (foodItem.servingWeightGrams || 100);
  }

  const factor = totalGrams / 100.0;
  const p100 = foodItem.per100g;

  const result = {
    grams: Math.round(totalGrams * 10) / 10,
    calories: Math.round(p100.calories * factor * 10) / 10,
    protein: Math.round(p100.protein * factor * 10) / 10,
    carbs: Math.round(p100.carbs * factor * 10) / 10,
    fat: Math.round(p100.fat * factor * 10) / 10,
    saturatedFat: Math.round(p100.saturatedFat * factor * 10) / 10,
    transFat: Math.round((p100.transFat || 0) * factor * 10) / 10,
    fiber: Math.round(p100.fiber * factor * 10) / 10,
    sugar: Math.round(p100.sugar * factor * 10) / 10,
    omega3: Math.round((p100.omega3 || 0) * factor * 100) / 100,
    omega6: Math.round((p100.omega6 || 0) * factor * 100) / 100,
    cholesterol: Math.round((p100.cholesterol || 0) * factor * 10) / 10,
    sodium: Math.round((p100.sodium || 0) * factor * 10) / 10,
    potassium: Math.round((p100.potassium || 0) * factor * 10) / 10,
    calcium: Math.round((p100.calcium || 0) * factor * 10) / 10,
    iron: Math.round((p100.iron || 0) * factor * 10) / 10,
    magnesium: Math.round((p100.magnesium || 0) * factor * 10) / 10,
    zinc: Math.round((p100.zinc || 0) * factor * 10) / 10,
    vitA: Math.round((p100.vitA || 0) * factor * 10) / 10,
    vitB1: Math.round((p100.vitB1 || 0) * factor * 100) / 100,
    vitB2: Math.round((p100.vitB2 || 0) * factor * 100) / 100,
    vitB3: Math.round((p100.vitB3 || 0) * factor * 10) / 10,
    vitB6: Math.round((p100.vitB6 || 0) * factor * 100) / 100,
    vitB12: Math.round((p100.vitB12 || 0) * factor * 100) / 100,
    vitC: Math.round((p100.vitC || 0) * factor * 10) / 10,
    vitD: Math.round((p100.vitD || 0) * factor * 10) / 10,
    vitE: Math.round((p100.vitE || 0) * factor * 10) / 10,
    vitK: Math.round((p100.vitK || 0) * factor * 10) / 10,
    folate: Math.round((p100.folate || 0) * factor * 10) / 10
  };

  return result;
}
